  document.querySelector('#match-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,o=Object.fromEntries(new FormData(f)),league=leaguesService.all().find(l=>String(l.id)===String(o.ligaId)),isNew=!o.id,isRest=o.tipo==='descanso';Object.assign(o,{torneo:league?.nombre||o.torneo,jornada:+o.jornada,duracion:isRest?0:+(o.duracion||league?.duracion||40),golesXolitas:isRest?0:+(o.golesXolitas||0),golesRival:isRest?0:+(o.golesRival||0),estado:isRest?'descanso':(o.estado||'programado')});const goals=[...f.querySelectorAll('[data-new-past-goal]')].map(input=>({playerId:input.dataset.newPastGoal,goals:+input.value||0})),assigned=goals.reduce((sum,x)=>sum+x.goals,0),needsAssignment=isNew&&!isRest&&o.estado==='finalizado'&&o.golesXolitas>0,error=f.querySelector('#new-past-goals-error');if(needsAssignment&&assigned!==o.golesXolitas){error.textContent=`Debes asignar exactamente ${o.golesXolitas} goles. Actualmente asignaste ${assigned}.`;showToast('La distribución de goleadoras no coincide con el marcador.','error');return}const button=f.querySelector('[type="submit"]');button.disabled=true;button.textContent='Guardando…';try{const saved=await matchesService.save(o);if(needsAssignment)await eventsService.setHistoricalGoals(saved.id,goals);f.closest('dialog').close();renderMatches(app,s);showToast(isNew?'Jornada guardada correctamente.':'Jornada actualizada correctamente.')}catch(error){button.disabled=false;button.textContent='Reintentar';showToast(`No se pudo guardar la jornada: ${error.message}`,'error')}});
