function matchDialog(){const options=leaguesService.all().map(l=>`<option value="${l.id}">${l.nombre}</option>`).join(''),goalInputs=playersService.all().filter(p=>p.activa).map(p=>`<label><span>#${p.numero} ${p.nombre} ${p.apellido||''}</span><input type="number" min="0" value="0" data-new-past-goal="${p.id}"></label>`).join('');return `<dialog id="match-dialog"><div class="modal-head"><h2>DATOS DE LA JORNADA</h2><button data-close>×</button></div><form class="form" id="match-form"><input type="hidden" name="id"><div class="field wide"><label>Tipo de jornada</label><select name="tipo"><option value="partido">Partido</option><option value="descanso">Descanso</option></select></div><div class="field"><label>Fecha</label><input name="fecha" type="date" required></div><div class="field"><label>Liga</label><select name="ligaId">${options}</select></div><div class="field"><label>Jornada</label><input name="jornada" type="number" min="1" required></div><div class="field match-only"><label>Rival</label><input name="rival" required></div><div class="field match-only"><label>Logo rival (URL)</label><input name="logoRival" type="url" placeholder="Opcional"></div><div class="field match-only"><label>Hora</label><input name="hora" type="time" required></div><div class="field match-only"><label>Lugar</label><input name="lugar" required></div><div class="field match-only"><label>Duración total (minutos)</label><input name="duracion" type="number" min="1" value="40" required></div><div class="field match-only"><label>Estado</label><select name="estado"><option value="programado">Programado</option><option value="finalizado">Partido pasado / finalizado</option></select></div><div class="field match-only"><label>Goles ${TEAM.shortName||TEAM.name}</label><input name="golesXolitas" type="number" min="0" value="0"></div><div class="field match-only"><label>Goles rival</label><input name="golesRival" type="number" min="0" value="0"></div><section class="wide past-goals-fields" id="new-past-goals" hidden><h3>¿Quiénes anotaron?</h3><p>Distribuye todos los goles de ${TEAM.shortName||TEAM.name} entre las jugadoras.</p><div class="goal-assignment-list">${goalInputs}</div><p class="error" id="new-past-goals-error"></p></section><div class="form-actions"><button type="button" class="secondary" data-close>Cancelar</button><button class="primary" type="submit">Guardar jornada</button></div></form></dialog>`}
function syncMatchTypeFields(){const f=document.querySelector('#match-form');if(!f)return;const rest=f.elements.tipo.value==='descanso';f.querySelectorAll('.match-only').forEach(el=>el.hidden=rest);['rival','hora','lugar','duracion'].forEach(name=>{if(f.elements[name])f.elements[name].required=!rest});syncPastGoalFields()}
