function leagueDialog(){return `<dialog id="league-dialog"><div class="modal-head"><h2 id="league-dialog-title">NUEVA LIGA</h2><button data-close>×</button></div><form class="form" id="league-form"><input type="hidden" name="id"><div class="field wide"><label>Nombre de la liga</label><input name="nombre" required></div><div class="field wide"><label>Duración predeterminada del partido (minutos)</label><input name="duracion" type="number" min="1" value="40" required></div><div class="form-actions"><button type="button" class="secondary" data-close>Cancelar</button><button class="primary" type="submit">Guardar liga</button></div></form></dialog>`}
