async function openHistoricalGoals(id){const match=matchesService.all().find(m=>String(m.id)===String(id)),d=document.querySelector('#historical-goals'),f=document.querySelector('#historical-goals-form');f.elements.matchId.value=id;document.querySelector('#historical-goals-copy').textContent=`Distribuye los ${match.golesXolitas} goles de ${TEAM.shortName||TEAM.name} contra ${match.rival}. Al guardar se reemplazará la asignación anterior.`;document.querySelector('#goal-assignment-list').innerHTML='<p class="empty">Cargando asignación…</p>';document.querySelector('#historical-goals-error').textContent='';d.showModal();try{await eventsService.sync(id);const totals=eventsService.forMatch(id).filter(e=>e.tipo==='gol_xolitas').reduce((map,e)=>(map[String(e.jugadoraId)]=(map[String(e.jugadoraId)]||0)+1,map),{});document.querySelector('#goal-assignment-list').innerHTML=playersService.all().filter(p=>p.activa).map(p=>`<label><span>#${p.numero} ${p.nombre} ${p.apellido||''}</span><input type="number" min="0" value="${totals[String(p.id)]||0}" data-goal-player="${p.id}"></label>`).join('')}catch(error){document.querySelector('#historical-goals-error').textContent=`No se pudo cargar la asignación: ${error.message}`}}
