  const draw=()=>{const rows=standingsService.all();document.querySelector('#standing-admin-list').innerHTML=`<div class="standing-admin-row standing-admin-head"><span>Pos</span><span>Equipo</span><span>Pts</span><span>J</span><span>G</span><span>E</span><span>P</span><span>GF</span><span>GC</span><span>Dif</span><span>%</span><span></span></div>${rows.map((row,index)=>`<div class="standing-admin-row ${/xolitas/i.test(row.equipo)?'is-xolitas':''}"><b>${index+1}</b><strong>${escapeAdmin(row.equipo)}</strong><b>${row.pts}</b><span>${row.j}</span><span>${row.g}</span><span>${row.e}</span><span>${row.p}</span><span>${row.gf}</span><span>${row.gc}</span><span>${row.dif>0?'+':''}${row.dif}</span><span>${row.porcentaje}</span><div><button data-standing-edit="${row.id}">Editar</button><button data-standing-delete="${row.id}">Eliminar</button></div></div>`).join('')}</div>`;bindStandingActions(draw)};
  document.querySelector('#new-standing').onclick=()=>openStanding();document.querySelectorAll('[data-close]').forEach(button=>button.onclick=()=>button.closest('dialog').close());draw();
