function standingDialog(){return `<dialog id="standing-dialog"><div class="modal-head"><h2 id="standing-title">AGREGAR EQUIPO</h2><button data-close>×</button></div><form class="form" id="standing-form"><input type="hidden" name="id"><div class="field wide"><label>Equipo</label><input name="equipo" required></div><div class="field wide"><label>Logo (URL opcional)</label><input name="logo" type="url" placeholder="https://..."></div><div class="field"><label>Ganados</label><input name="g" type="number" min="0" value="0" required></div><div class="field"><label>Empatados</label><input name="e" type="number" min="0" value="0" required></div><div class="field"><label>Perdidos</label><input name="p" type="number" min="0" value="0" required></div><div class="field"><label>Goles a favor</label><input name="gf" type="number" min="0" value="0" required></div><div class="field"><label>Goles en contra</label><input name="gc" type="number" min="0" value="0" required></div><div class="field"><label>Puntos extra o penalización</label><input name="pe" type="number" value="0"></div><div class="standing-calculation wide" id="standing-calculation"></div><p class="error wide" id="standing-error"></p><div class="form-actions"><button type="button" class="secondary" data-close>Cancelar</button><button class="primary" type="submit">Guardar equipo</button></div></form></dialog>`}
function openStanding(row={}){const dialog=document.querySelector('#standing-dialog'),form=document.querySelector('#standing-form');form.reset();['id','equipo','logo','g','e','p','gf','gc','pe'].forEach(key=>{if(form.elements[key])form.elements[key].value=row[key]??(key==='id'||key==='equipo'||key==='logo'?'':0)});document.querySelector('#standing-title').textContent=row.id?'EDITAR EQUIPO':'AGREGAR EQUIPO';updateStandingPreview();dialog.showModal()}
function calculateStanding(form){const g=+form.elements.g.value||0,e=+form.elements.e.value||0,p=+form.elements.p.value||0,gf=+form.elements.gf.value||0,gc=+form.elements.gc.value||0,pe=+form.elements.pe.value||0,j=g+e+p,pts=g*3+e+pe;return{g,e,p,gf,gc,pe,j,pts,dif:gf-gc,porcentaje:j?Math.round(pts/(j*3)*100):0}}
function updateStandingPreview(){const form=document.querySelector('#standing-form');if(!form)return;const row=calculateStanding(form);document.querySelector('#standing-calculation').innerHTML=`<b>${row.pts} puntos</b><span>${row.j} jugados · Diferencia ${row.dif>0?'+':''}${row.dif} · ${row.porcentaje}% efectividad</span>`}
function bindStandingActions(draw){document.querySelectorAll('[data-standing-edit]').forEach(button=>button.onclick=()=>openStanding(standingsService.all().find(row=>String(row.id)===String(button.dataset.standingEdit))));document.querySelectorAll('[data-standing-delete]').forEach(button=>button.onclick=async()=>{if(!confirm('¿Eliminar este equipo de la clasificación?'))return;try{await standingsService.remove(button.dataset.standingDelete);draw();showToast('Equipo eliminado de la clasificación.')}catch(error){showToast(error.message,'error')}});const form=document.querySelector('#standing-form');form.querySelectorAll('input[type="number"]').forEach(input=>input.oninput=updateStandingPreview);form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('[type="submit"]'),error=document.querySelector('#standing-error'),data=Object.fromEntries(new FormData(form));Object.assign(data,calculateStanding(form));button.disabled=true;button.textContent='Guardando…';error.textContent='';try{await standingsService.save(data);form.closest('dialog').close();renderStandings(document.querySelector('#admin-app'),authService.require());showToast('Clasificación actualizada.')}catch(err){error.textContent=err.message;button.disabled=false;button.textContent='Reintentar'}}}
function sponsorDialog(){return `<dialog id="sponsor-dialog"><div class="modal-head"><h2 id="sponsor-title">NUEVO PATROCINADOR</h2><button data-close>×</button></div><form class="form" id="sponsor-form"><input type="hidden" name="id"><input type="hidden" name="logo"><div class="field wide"><label>Nombre</label><input name="nombre" required></div><div class="field wide"><label>Logo (PNG, JPG o WebP, máximo 3 MB)</label><input name="logoFile" type="file" accept="image/png,image/jpeg,image/webp"><div class="sponsor-preview" id="sponsor-preview">Vista previa</div></div><div class="field wide"><label>Sitio web (opcional)</label><input name="sitio" type="url" placeholder="https://..."></div><div class="field"><label>Orden</label><input name="orden" type="number" min="0" value="0"></div><div class="field"><label><input name="activo" type="checkbox" checked> Visible</label></div><p class="error wide" id="sponsor-error"></p><div class="form-actions"><button type="button" class="secondary" data-close>Cancelar</button><button class="primary" type="submit">Guardar patrocinador</button></div></form></dialog>`}
function openSponsor(sponsor={}){const dialog=document.querySelector('#sponsor-dialog'),form=document.querySelector('#sponsor-form');form.reset();form.elements.id.value=sponsor.id||'';form.elements.nombre.value=sponsor.nombre||'';form.elements.logo.value=sponsor.logo||'';form.elements.sitio.value=sponsor.sitio||'';form.elements.orden.value=sponsor.orden||0;form.elements.activo.checked=sponsor.activo!==false;document.querySelector('#sponsor-title').textContent=sponsor.id?'EDITAR PATROCINADOR':'NUEVO PATROCINADOR';showSponsorPreview(sponsor.logo);dialog.showModal()}
function bindSponsors(draw){document.querySelectorAll('[data-edit-sponsor]').forEach(button=>button.onclick=()=>openSponsor(sponsorsService.all().find(s=>String(s.id)===String(button.dataset.editSponsor))));document.querySelectorAll('[data-delete-sponsor]').forEach(button=>button.onclick=async()=>{if(!confirm('¿Eliminar este patrocinador?'))return;try{await sponsorsService.remove(button.dataset.deleteSponsor);draw();showToast('Patrocinador eliminado.')}catch(error){showToast(`No se pudo eliminar: ${error.message}`,'error')}});const form=document.querySelector('#sponsor-form');form.elements.logoFile.onchange=()=>{const file=form.elements.logoFile.files[0];if(file)showSponsorPreview(URL.createObjectURL(file))};form.onsubmit=async event=>{event.preventDefault();const file=form.elements.logoFile.files[0],error=document.querySelector('#sponsor-error');error.textContent='';if(!form.elements.id.value&&!file){error.textContent='Selecciona una imagen para el patrocinador.';return}if(file&&file.size>3*1024*1024){error.textContent='La imagen supera el máximo de 3 MB.';return}const button=form.querySelector('[type="submit"]');button.disabled=true;button.textContent='Subiendo…';try{const data=Object.fromEntries(new FormData(form));delete data.logoFile;data.activo=form.elements.activo.checked;data.orden=+data.orden||0;if(file){data.logoData=await fileToDataURL(file);data.fileName=file.name;data.mimeType=file.type}await sponsorsService.save(data);form.closest('dialog').close();renderSponsors(document.querySelector('#admin-app'),authService.require());showToast('Patrocinador guardado correctamente.')}catch(err){error.textContent=err.message;button.disabled=false;button.textContent='Reintentar'}}}
function showSponsorPreview(url){document.querySelector('#sponsor-preview').innerHTML=url?`<img src="${escapeAdmin(url)}" alt="Vista previa">`:'Vista previa'}
function fileToDataURL(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('No se pudo leer la imagen'));reader.readAsDataURL(file)})}
function escapeAdmin(value=''){const span=document.createElement('span');span.textContent=String(value);return span.innerHTML}
function installUploadStyles(){if(document.querySelector('#upload-styles'))return;const style=document.createElement('style');style.id='upload-styles';style.textContent='.image-upload-preview{min-height:130px;border:1px dashed #d2a0bc;background:#faf6f0;display:grid;place-items:center;color:#746574;font-size:10px}.image-upload-preview img{width:100%;height:150px;object-fit:contain;padding:10px}.field textarea{border:1px solid #ddcfd8;padding:12px;resize:vertical;font:inherit}';document.head.appendChild(style)}
function showImagePreview(selector,url){const host=document.querySelector(selector);if(host)host.innerHTML=url?`<img src="${escapeAdmin(url)}" alt="Vista previa">`:'Vista previa'}
function previewSelectedFile(input,selector,fallbackUrl=''){input.setCustomValidity('');const file=input.files[0];if(!file){showImagePreview(selector,fallbackUrl);return}if(file.size>3*1024*1024){input.setCustomValidity('La imagen supera el máximo de 3 MB');input.reportValidity();return}showImagePreview(selector,URL.createObjectURL(file))}
function installRivalUploadField(){const form=document.querySelector('#match-form');if(!form||document.querySelector('#rival-logo-file'))return;const field=document.createElement('div');field.className='field wide match-only rival-upload-field';field.innerHTML=`<label>Subir escudo rival (PNG, JPG o WebP, máximo 3 MB)</label><input id="rival-logo-file" type="file" accept="image/png,image/jpeg,image/webp"><input type="hidden" name="logoData"><input type="hidden" name="fileName"><input type="hidden" name="mimeType"><div class="image-upload-preview" id="rival-logo-preview">Vista previa</div>`;form.querySelector('.form-actions').before(field);field.querySelector('#rival-logo-file').onchange=async event=>{const file=event.target.files[0];if(!file)return;if(file.size>3*1024*1024){event.target.setCustomValidity('La imagen supera el máximo de 3 MB');event.target.reportValidity();return}event.target.setCustomValidity('');showImagePreview('#rival-logo-preview',URL.createObjectURL(file));form.elements.logoData.value=await fileToDataURL(file);form.elements.fileName.value=file.name;form.elements.mimeType.value=file.type}}

async function renderTeamSettings(app,s){
  if(!authService.can('manageTeam')){app.innerHTML=shell(s,'IDENTIDAD','Sin permiso','<p class="empty">Tu rol no permite cambiar la identidad del equipo.</p>');return}
  const {team,branding,settings}=await window.Xolitas.platformService.getCurrentTeam(),labels=settings.labels||{},copy=settings.copy||{},modules=settings.modules||{};
  app.innerHTML=shell(s,'IDENTIDAD DEL EQUIPO','La estructura visual de Xolitas se conserva; aquí cambias identidad y contenido.',`<div class="settings-grid"><div><form class="panel form" id="team-settings-form">
    <h2 class="wide">DATOS GENERALES</h2>
    <div class="field"><label>Nombre del equipo</label><input name="name" value="${escapeAdmin(team.name||'')}" required></div>
    <div class="field"><label>Nombre corto</label><input name="short_name" value="${escapeAdmin(team.short_name||'')}" required></div>
    <div class="field wide"><label>Logo</label><input id="team-logo-file" type="file" accept="image/png,image/jpeg,image/webp"><input type="hidden" name="logo_url" value="${escapeAdmin(team.logo_url||'')}"><div class="image-upload-preview" id="team-logo-preview">${team.logo_url?`<img src="${escapeAdmin(team.logo_url)}" alt="Logo">`:'Vista previa'}</div></div>
    <div class="field"><label>Frase superior</label><input name="eyebrow" value="${escapeAdmin(team.eyebrow||'')}"></div>
    <div class="field"><label>Lema</label><input name="tagline" value="${escapeAdmin(team.tagline||'')}"></div>
    <h2 class="wide">COLORES DEL SITIO</h2>
    <div class="field wide color-grid">${colorField('primary_color','Principal',branding.primary_color)}${colorField('secondary_color','Secundario',branding.secondary_color)}${colorField('accent_color','Acento / dorado',branding.accent_color)}${colorField('background_color','Fondo',branding.background_color)}${colorField('text_color','Texto',branding.text_color)}${colorField('dashboard_primary_color','Dashboard principal',branding.dashboard_primary_color)}${colorField('dashboard_sidebar_color','Sidebar',branding.dashboard_sidebar_color)}${colorField('dashboard_button_color','Botones',branding.dashboard_button_color)}</div>
    <h2 class="wide">TEXTOS DE LA PLANTILLA</h2>
    ${textField('calendar_title_1','Calendario · línea 1',labels.calendar_title_1||'HUELLAS EN')}${textField('calendar_title_2','Calendario · línea 2',labels.calendar_title_2||'LA CANCHA')}
    ${textField('roster_title_1','Plantilla · línea 1',labels.roster_title_1||'NUESTRA')}${textField('roster_title_2','Plantilla · línea 2',labels.roster_title_2||'MANADA')}
    ${textField('stats_title_1','Goleadoras · línea 1',labels.stats_title_1||'LAS QUE')}${textField('stats_title_2','Goleadoras · línea 2',labels.stats_title_2||'DEFINEN.')}
    ${textField('club_title_1','Club · línea 1',labels.club_title_1||'DEJAMOS')}${textField('club_title_2','Club · línea 2',labels.club_title_2||'HUELLA.')}
    <div class="field wide"><label>Texto hero (admite &lt;br&gt;)</label><textarea name="hero_tagline" rows="3">${escapeAdmin(copy.hero_tagline||team.tagline||'')}</textarea></div>
    <div class="field wide"><label>Descripción de plantilla</label><textarea name="roster_desc" rows="3">${escapeAdmin(copy.roster_desc||'')}</textarea></div>
    <div class="field wide"><label>Descripción de estadísticas</label><textarea name="stats_desc" rows="3">${escapeAdmin(copy.stats_desc||'')}</textarea></div>
    <h2 class="wide">SECCIONES PÚBLICAS</h2><div class="wide module-list">${['calendar','standings','roster','stats','club','sponsors','next_match','live_match'].map(k=>`<label><input type="checkbox" name="module_${k}" ${modules[k]!==false?'checked':''}> ${moduleName(k)}</label>`).join('')}</div>
    <div class="field wide"><label><input type="checkbox" name="public_site_enabled" ${team.public_site_enabled!==false?'checked':''}> Página pública habilitada</label></div>
    <div class="form-actions"><button class="primary" type="submit">Guardar identidad</button></div>
  </form></div><aside class="settings-preview panel"><h2>VISTA PREVIA</h2><div class="preview-hero" id="settings-preview"><img src="${escapeAdmin(team.logo_url||TEAM.logo)}" alt=""><div><small>${escapeAdmin(team.eyebrow||'')}</small><h2>${escapeAdmin(team.short_name||team.name)}<br><em>${escapeAdmin(labels.hero_title_2||'')}</em></h2><p>${escapeAdmin(team.tagline||'')}</p></div></div><p><a href="${window.TeamContext.publicUrl}" target="_blank">Abrir sitio público →</a></p></aside></div>`);
  const form=document.querySelector('#team-settings-form'),logoFile=document.querySelector('#team-logo-file');
  logoFile.onchange=()=>{const file=logoFile.files[0];if(file)showImagePreview('#team-logo-preview',URL.createObjectURL(file));updatePreview()};
  form.querySelectorAll('input,textarea').forEach(x=>x.addEventListener('input',updatePreview));
  function updatePreview(){const p=document.querySelector('#settings-preview');p.style.background=`linear-gradient(140deg,${form.primary_color.value},${form.secondary_color.value})`;p.querySelector('small').textContent=form.eyebrow.value;p.querySelector('h2').firstChild.textContent=form.short_name.value;p.querySelector('p').textContent=form.tagline.value;if(logoFile.files[0])p.querySelector('img').src=URL.createObjectURL(logoFile.files[0])}
  form.onsubmit=async e=>{e.preventDefault();const btn=form.querySelector('[type=submit]');btn.disabled=true;btn.textContent='Guardando…';try{let logo=team.logo_url;if(logoFile.files[0])logo=await window.Xolitas.platformService.uploadTeamFile(logoFile.files[0],'branding');const d=Object.fromEntries(new FormData(form));const nextTeam={...team,name:d.name,short_name:d.short_name,logo_url:logo,eyebrow:d.eyebrow,tagline:d.tagline,public_site_enabled:form.public_site_enabled.checked};const nextBrand={...branding};['primary_color','secondary_color','accent_color','background_color','text_color','dashboard_primary_color','dashboard_sidebar_color','dashboard_button_color'].forEach(k=>nextBrand[k]=d[k]);const nextLabels={...labels};['calendar_title_1','calendar_title_2','roster_title_1','roster_title_2','stats_title_1','stats_title_2','club_title_1','club_title_2'].forEach(k=>nextLabels[k]=d[k]);const nextModules={...modules};['calendar','standings','roster','stats','club','sponsors','next_match','live_match'].forEach(k=>nextModules[k]=form[`module_${k}`].checked);const nextCopy={...copy,hero_tagline:d.hero_tagline,roster_desc:d.roster_desc,stats_desc:d.stats_desc};await window.Xolitas.platformService.saveCurrentTeam({team:nextTeam,branding:nextBrand,settings:{...settings,labels:nextLabels,modules:nextModules,copy:nextCopy}});showToast('Identidad guardada. La página pública ya usa estos cambios.');setTimeout(()=>location.reload(),600)}catch(err){showToast(err.message,'error');btn.disabled=false;btn.textContent='Guardar identidad'}};
}
function colorField(name,label,value){return `<div class="color-field"><input type="color" name="${name}" value="${escapeAdmin(value||'#351137')}"><div class="field"><label>${label}</label><input value="${escapeAdmin(value||'')}" data-color-text="${name}" oninput="this.form.${name}.value=this.value"></div></div>`}
function textField(name,label,value){return `<div class="field"><label>${label}</label><input name="${name}" value="${escapeAdmin(value||'')}"></div>`}
function moduleName(k){return({calendar:'Calendario / jornadas',standings:'Clasificación',roster:'Plantilla',stats:'Goleadoras',club:'Club / manifiesto',sponsors:'Patrocinadores',next_match:'Próximo partido',live_match:'Modo partido'})[k]||k}

async function renderMembers(app,s){
 if(!authService.can('manageMembers')){app.innerHTML=shell(s,'USUARIOS','Permisos','<p class="empty">Tu rol no permite administrar usuarios.</p>');return}
 const rows=await window.Xolitas.platformService.members(window.Xolitas.team.organization_id);
 app.innerHTML=shell(s,'USUARIOS Y PERMISOS','Cada organización mantiene sus accesos separados.',`<section class="panel"><h2>INVITAR USUARIO</h2><form id="invite-form" class="form"><div class="field"><label for="invite-email">Correo</label><input id="invite-email" name="email" type="email" autocomplete="email" maxlength="254" required></div><div class="field"><label for="invite-role">Rol</label><select id="invite-role" name="role">${(s.organizationRole||s.role)==='owner'?'<option value="owner">Owner</option>':''}<option value="admin">Admin</option><option value="capturista" selected>Capturista</option><option value="entrenador">Entrenador</option><option value="viewer">Viewer</option></select></div><div class="form-actions"><button class="primary" type="submit">Enviar invitación</button></div></form></section><section class="panel" style="margin-top:16px"><h2>MIEMBROS E INVITACIONES</h2><table class="table-admin"><thead><tr><th>Usuario</th><th>Rol</th><th>Estado</th></tr></thead><tbody id="members-list">${memberRows(rows)}</tbody></table></section>`);
 document.querySelector('#invite-form').onsubmit=async event=>{
  event.preventDefault();
  const form=event.currentTarget,button=form.querySelector('[type="submit"]');
  if(button.disabled)return;
  button.disabled=true;button.textContent='Enviando…';
  try{
   const result=await window.Xolitas.platformService.inviteMember(window.Xolitas.team.organization_id,form.elements.email.value,form.elements.role.value);
   showToast(result.message);form.reset();
   try{document.querySelector('#members-list').innerHTML=memberRows(await window.Xolitas.platformService.members(window.Xolitas.team.organization_id))}catch{showToast('La operación terminó, pero no se pudo actualizar la lista. Recarga la página.','error')}
  }catch(error){showToast(error.message,'error')}
  finally{button.disabled=false;button.textContent='Enviar invitación'}
 };
}
function memberRows(rows){return rows.map(row=>`<tr><td>${escapeAdmin(row.email||row.user_id||'Usuario')}</td><td>${escapeAdmin(row.role)}</td><td>${escapeAdmin(row.status)}</td></tr>`).join('')||'<tr><td colspan="3">Aún no hay miembros visibles.</td></tr>'}

async function renderSubscription(app,s){const sub=await window.Xolitas.platformService.subscriptionForOrg(window.Xolitas.team.organization_id);const plans=await window.Xolitas.platformService.listPlans(),features=await window.Xolitas.platformService.listPlanFeatures();const plan=plans.find(p=>p.id===sub?.plan_id)||sub?.plans;app.innerHTML=shell(s,'PLAN','Suscripción y funciones habilitadas',`<section class="panel"><h2>${escapeAdmin(plan?.name||'Sin plan asignado')}</h2><p>Estado: <span class="badge">${escapeAdmin(sub?.status||'sin suscripción')}</span></p><p>${plan?`$${Number(plan.monthly_price_mxn||0).toLocaleString('es-MX')} MXN / mes`:'La organización todavía no tiene plan.'}</p></section><section class="panel" style="margin-top:16px"><h2>FUNCIONES</h2><div class="data-grid">${features.filter(f=>!plan||f.plan_id===plan.id).map(f=>`<article class="data-card"><h3>${escapeAdmin(f.feature_code||f.code||'Función')}</h3><p>${f.enabled===false?'No incluida':'Incluida'}${f.limit_value?` · límite ${f.limit_value}`:''}</p></article>`).join('')||'<p class="empty">Las funciones se administran desde Super Admin.</p>'}</div></section>`)}
